      "raw_utf8": "{\n  \"AuthorityEffect\": \"None\",\n  \"artifact\": {\n    \"path\": \"code/python/src/finite_probability/__init__.py\",\n    \"sha256\": \"f7a0064065347ed81808814dcd313706d70b41a619f81bc484ef42d0b8f3f87f\"\n  },\n  \"claim\": \"urn:omega:fqm:simplex:scaled-integer-separator:v1\",\n  \"profile\": \"Exact\",\n  \"role\": \"library and entrypoint\",\n  \"purpose\": \"Bounded signed integer-pair mass and named normalization/nonnegativity separators.\",\n  \"operations\": {\n    \"integer_mass\": \"Require a built-in tuple of two built-in integers of at most 1024 bits; signed weights are admitted. Return their exact sum, which may require one extra bit.\",\n    \"scaled_simplex_witness\": \"Check point (1,0), signed (-1,2), double (1,1) and the zero self-gap; return the point mass 1.\",\n    \"main\": \"Print 1 and return 0 for the fixed witness; output unavailable returns 2.\"\n  },\n  \"engineering_policy\": \"Two scalar inputs with a 1024-bit engineering envelope; no caller-controlled loop or allocation. Boolean and scalar/container subclasses are refused.\",\n  \"policy_origin\": \"Declared engineering limits, not empirical measurements or derived physical constants.\",\n  \"failure_boundary\": \"ScaledSimplexError carries invariant and role for admission, arity, bit budget and witness failures. Output IO refusal returns 2.\",\n  \"cost_model\": \"One bounded arbitrary-precision integer addition for the public mass operation; fixed additional witness checks.\",\n  \"scope_ceiling\": \"Not a rational probability-simplex constructor, canonical metric selection or Lean proof.\",\n  \"trust\": \"Pinned CPython and providers in the challenge inputs. Type-based checks avoid value.__class__ and container/scalar overrides. This is not a security sandbox for arbitrary metaclass hooks, monkeypatching, hostile interpreter state, host exhaustion or deliberate reflection.\",\n  \"negative_float_fixture_policy\": \"Tests may deliberately supply binary floats only as rejection probes under SCORING.md.\",\n  \"evidence\": [\n    {\n      \"path\": \"evidence/quality/expanded_scope/20261020T212330Z-entrypoints-challenge/receipt.json\",\n      \"sha256\": \"b7c426b9fb3b58c0f80ca3a6af8bbe82db83333f8046af728dcb10f22d684a49\"\n    },\n    {\n      \"path\": \"evidence/quality/expanded_scope/20261020T212358Z-source-metrics/receipt.json\",\n      \"sha256\": \"395b619a318a5b519b9b2b11f24b7bc76ae1a373c3f2fb16220d13ad69b52d68\"\n    },\n    {\n      \"path\": \"evidence/quality/expanded_scope/batch2-baseline.log\",\n      \"sha256\": \"ac4614164e22c790103ce4db5a662da099a1027b7b96a131e748f88b9a843169\"\n    },\n    {\n      \"path\": \"evidence/quality/expanded_scope/batch2-atlas.log\",\n      \"sha256\": \"45425bc105e799841cffa39d959410b2947cb7f8fb62879199a2fa95f302b7f3\"\n    }\n  ]\n}\n",
